bg=4
colors=[1,7,9]
patterns={1:[[1,0,1],[1,1,1],[1,1,0]],7:[[1,0,1],[0,1,1],[1,0,1]],9:[[1,1,0],[1,0,0],[1,1,1]]}
out=[[bg]*19 for _ in range(7)]
for k,c in enumerate(colors):
    x0=1+k*6
    for y in [1,5]:
        for x in range(x0,x0+5): out[y][x]=c
    for y in range(1,6): out[y][x0]=out[y][x0+4]=c
    for dy in range(3):
        for dx in range(3): out[2+dy][x0+1+dx]=bg if patterns[c][dy][dx] else c
out
